def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('--dataset', required=True,
                        help='Generated single-frame corrupted-cloud pickles.')
    parser.add_argument('--annos_dir', required=True,
                        help='Subset selector: *_a.pkl stems pick segments.')
    parser.add_argument('--cfg_file', required=True, help='CP4F cfg yaml.')
    parser.add_argument('--ckpt', required=True, help='CP4F checkpoint.')
    parser.add_argument('--pred_dir', required=True,
                        help='Checkpoint-specific per-segment predictions.')
    parser.add_argument('--identity_json', required=True,
                        help='Guards resume against checkpoint/config changes.')
    parser.add_argument('--metrics_json', required=True)
    parser.add_argument('--summary_pkl', required=True)
    parser.add_argument('--label', required=True)
    parser.add_argument('--data_path', default=None,
                        help='Override cfg.DATA_CONFIG.DATA_PATH.')
    parser.add_argument('--workers', type=int, default=4)
    parser.add_argument('--resume', type=int, choices=(0, 1), default=1)
    return parser.parse_args()


def setup_logger(name):
    logger = logging.getLogger(name)
    logger.setLevel(logging.INFO)
    logger.handlers.clear()
    handler = logging.StreamHandler()
    handler.setFormatter(logging.Formatter(
        '%(asctime)s | %(levelname)s | %(message)s'
    ))
    logger.addHandler(handler)
    logger.propagate = False
    return logger


def to_numpy(value, dtype=None):
    if value is None:
        return None
    if isinstance(value, torch.Tensor):
        value = value.detach().cpu().numpy()
    else:
        value = np.asarray(value)
    if dtype is not None:
        value = value.astype(dtype, copy=False)
    return value


def inject_gt_names(data_dict, class_names):
    if 'gt_boxes' in data_dict and 'gt_names' not in data_dict:
        boxes = to_numpy(data_dict['gt_boxes'])
        labels = boxes[:, -1].astype(np.int64)
        if np.any(labels < 1) or np.any(labels > len(class_names)):
            raise ValueError(
                'Invalid GT labels while reconstructing gt_names: '
                f'{np.unique(labels)}'
            )
        data_dict['gt_names'] = np.asarray([
            class_names[label - 1] for label in labels
        ])
    return data_dict


def dataset_file(dataset_dir, segment):
    dataset_dir = Path(dataset_dir)
    for path in (
        dataset_dir / f'{segment}.pkl',
        dataset_dir / f'{segment}_d.pkl',
    ):
        if path.is_file():
            return path
    raise FileNotFoundError(
        f'No dataset pickle for segment {segment!r} in {dataset_dir}'
    )


def discover_selected_segments(dataset_dir, annos_dir):
    anno_paths = sorted(Path(annos_dir).glob('*_a.pkl'))
    if not anno_paths:
        raise RuntimeError(f'No *_a.pkl files found in {annos_dir}')
    segments = [path.stem[:-2] for path in anno_paths]
    for segment in segments:
        dataset_file(dataset_dir, segment)
    return segments


def segment_name_from_info(info):
    return str(info['point_cloud']['lidar_sequence'])


def filter_dataset_to_selected_segments(dataset, selected_segments):
    selected = set(selected_segments)
    dataset.infos = [
        info for info in dataset.infos
        if segment_name_from_info(info) in selected
    ]
    present = {segment_name_from_info(info) for info in dataset.infos}
    missing = selected - present
    if missing:
        raise RuntimeError(
            'Selected segments absent from CP4F dataset infos: '
            + ', '.join(sorted(missing))
        )
    if not dataset.infos:
        raise RuntimeError('Filtering left zero evaluation frames')


def build_index_maps(dataset):
    global_to_segment = {}
    counts = {}
    pose_map = {}
    ordered_segments = []
    seen = set()

    for global_idx, info in enumerate(dataset.infos):
        segment = segment_name_from_info(info)
        local_idx = counts.get(segment, 0)
        counts[segment] = local_idx + 1
        global_to_segment[global_idx] = (segment, local_idx)

        if 'pose' not in info:
            raise KeyError(
                f'Missing pose in CP4F info for {segment}[{local_idx}]'
            )
        pose_map[(segment, local_idx)] = np.asarray(
            info['pose'], dtype=np.float64
        ).reshape(4, 4)

        if segment not in seen:
            ordered_segments.append(segment)
            seen.add(segment)

    return global_to_segment, counts, pose_map, ordered_segments


def atomic_pickle_dump(value, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + '.tmp')
    with open(temp, 'wb') as handle:
        pkl.dump(value, handle)
    os.replace(temp, path)


def json_default(value):
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, torch.Tensor):
        return value.detach().cpu().tolist()
    raise TypeError(f'Not JSON serializable: {type(value).__name__}')


def atomic_json_dump(value, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + '.tmp')
    with open(temp, 'w', encoding='utf-8') as handle:
        json.dump(value, handle, indent=2, sort_keys=True,
                  default=json_default)
    os.replace(temp, path)


def check_or_write_identity(args):
    identity = {
        'dataset_dir': str(Path(args.dataset).resolve()),
        'annos_dir': str(Path(args.annos_dir).resolve()),
        'cfg_file': str(Path(args.cfg_file).resolve()),
        'ckpt': str(Path(args.ckpt).resolve()),
        'label': args.label,
        'aggregation': 'recomputed_4frame_from_generated_singleframe_clouds',
    }
    path = Path(args.identity_json)
    if path.is_file():
        with open(path, 'r', encoding='utf-8') as handle:
            previous = json.load(handle)
        if previous != identity:
            raise RuntimeError(
                'Existing result directory belongs to a different run identity. '
                'Use a new LABEL or delete the result directory.\n'
                f'Existing: {json.dumps(previous, indent=2, sort_keys=True)}\n'
                f'Requested: {json.dumps(identity, indent=2, sort_keys=True)}'
            )
    else:
        atomic_json_dump(identity, path)
    return identity


def validate_completed_segments(pred_dir, ordered_segments, counts):
    completed = set()
    pred_dir = Path(pred_dir)
    for segment in ordered_segments:
        path = pred_dir / f'{segment}_p.pkl'
        if not path.is_file():
            continue
        try:
            with open(path, 'rb') as handle:
                preds = pkl.load(handle)
            if len(preds) != counts[segment]:
                continue
            if any(str(pred.get('frame_id')) == 'None' for pred in preds):
                continue
            completed.add(segment)
        except Exception:
            continue
    return completed


def load_all_predictions(pred_dir, ordered_segments, counts):
    all_preds = {}
    for segment in ordered_segments:
        path = Path(pred_dir) / f'{segment}_p.pkl'
        if not path.is_file():
            raise FileNotFoundError(f'Missing prediction file: {path}')
        with open(path, 'rb') as handle:
            preds = pkl.load(handle)
        if len(preds) != counts[segment]:
            raise RuntimeError(
                f'Prediction count mismatch for {segment}: '
                f'{len(preds)} != {counts[segment]}'
            )
        all_preds[segment] = preds
    return all_preds


def assemble_det_annos(dataset, segment_predictions):
    counters = {}
    det_annos = []
    for info in dataset.infos:
        segment = segment_name_from_info(info)
        local_idx = counters.get(segment, 0)
        prediction = segment_predictions[segment][local_idx]
        if str(prediction['frame_id']) != str(info['frame_id']):
            raise AssertionError(
                f'Frame mismatch at {segment}[{local_idx}]: '
                f"pred={prediction['frame_id']} info={info['frame_id']}"
            )
        det_annos.append(prediction)
        counters[segment] = local_idx + 1
    return det_annos


def frame_is_modified(segment_data, local_idx):
    frame = segment_data[local_idx]
    if 'modified_this_frame' in frame:
        return bool(frame['modified_this_frame'])
    return frame.get('spoof_gt') is not None


def calculate_full_aggregation_stats(dataset_dir, ordered_segments, counts):
    stats = {
        'native_clean_window': 0,
        'rebuilt_corrupted_window': 0,
    }
    for segment in ordered_segments:
        with open(dataset_file(dataset_dir, segment), 'rb') as handle:
            segment_data = pkl.load(handle)
        if len(segment_data) != counts[segment]:
            raise RuntimeError(
                f'Dataset length mismatch for {segment}: '
                f'{len(segment_data)} != {counts[segment]}'
            )
        for local_idx in range(counts[segment]):
            lag_indices = [max(local_idx - lag, 0) for lag in range(4)]
            any_modified = any(
                frame_is_modified(segment_data, idx) for idx in lag_indices
            )
            key = (
                'rebuilt_corrupted_window' if any_modified
                else 'native_clean_window'
            )
            stats[key] += 1
    return stats


def build_cp4f_item(dataset, global_idx, segment, local_idx,
                     segment_data, pose_map):
    """Return one CP4F-ready item and whether its 4-frame cloud was rebuilt.

    Rebuild semantics match the CP4F proposal stage used by the MSF injection
    evaluator: [t,t-1,t-2,t-3], clamped at segment start; every historical
    cloud is transformed into the current ego frame; the final point feature
    is overwritten with 0.1 * lag.
    """
    lag_indices = [max(local_idx - lag, 0) for lag in range(4)]
    any_modified = any(
        frame_is_modified(segment_data, idx) for idx in lag_indices
    )

    if not any_modified:
        return dataset[global_idx], False

    pose_cur = pose_map[(segment, local_idx)]
    pose_cur_inv = np.linalg.inv(pose_cur)
    merged = []

    for lag_idx in lag_indices:
        points = to_numpy(segment_data[lag_idx]['points'], np.float32).copy()
        if points.ndim != 2 or points.shape[1] < 4:
            raise ValueError(
                f'Invalid points shape at {segment}[{lag_idx}]: {points.shape}'
            )

        # Generated clouds are single-frame clouds with a lag feature. Replace
        # that final feature with the lag relative to the current CP4F frame.
        points[:, -1] = (local_idx - lag_idx) * 0.1

        pose_lag = pose_map[(segment, lag_idx)]
        ones = np.ones((points.shape[0], 1), dtype=points.dtype)
        hom = np.hstack((points[:, :3], ones))
        xyz_current = hom @ pose_lag.T @ pose_cur_inv.T
        merged.append(np.hstack((xyz_current[:, :3], points[:, 3:])))

    aggregated = np.vstack(merged).astype(np.float32, copy=False)

    # Use the CP4F dataloader item for frame metadata / GT, but replace its
    # native clean pre-aggregation and re-run CP4F preprocessing/voxelization.
    data_dict = dataset[global_idx].copy()
    for key in ('voxels', 'voxel_coords', 'voxel_num_points'):
        data_dict.pop(key, None)
    data_dict['points'] = aggregated
    data_dict = inject_gt_names(data_dict, dataset.class_names)
    data_dict = dataset.prepare_data(data_dict)
    return data_dict, True


# -------------------------------------------------------------------------
# Injection and Waymo metric helpers (same semantics as eval_injection_msf.sh)
# -------------------------------------------------------------------------
def prediction_arrays(frame_pred):
    boxes = frame_pred.get('boxes_lidar', frame_pred.get('pred_boxes'))
    labels = frame_pred.get('pred_labels')
    scores = frame_pred.get('score', frame_pred.get('pred_scores'))
    boxes = to_numpy(boxes, np.float32)
    labels = to_numpy(labels, np.int64)
    scores = to_numpy(scores, np.float32)
    if boxes is None:
        boxes = np.empty((0, 7), dtype=np.float32)
    if labels is None:
        labels = np.empty((0,), dtype=np.int64)
    if scores is None:
        scores = np.empty((0,), dtype=np.float32)
    return boxes, labels, scores


def spoof_false_positive(frame_pred, spoof_box):
    pred_boxes, pred_labels, pred_scores = prediction_arrays(frame_pred)
    if len(pred_boxes) == 0:
        return None
    spoof = to_numpy(spoof_box, np.float32).reshape(-1)[:7]
    pred_tensor = torch.as_tensor(
        pred_boxes[:, :7], dtype=torch.float32, device='cuda'
    )
    gt_tensor = torch.as_tensor(
        spoof, dtype=torch.float32, device='cuda'
    ).unsqueeze(0)
    ious = iou3d_nms_utils.boxes_iou3d_gpu(pred_tensor, gt_tensor)[:, 0]
    best_idx = int(torch.argmax(ious).item())
    max_iou = float(ious[best_idx].item())
    label = int(pred_labels[best_idx])
    score = float(pred_scores[best_idx])
    if label == 1:
        is_fp = max_iou >= 0.7
    elif label in (2, 3):
        is_fp = max_iou >= 0.5
    else:
        is_fp = False
    return {
        'max_iou': max_iou,
        'label': label,
        'score': score,
        'is_fp': bool(is_fp),
    }


def score_statistics(scores):
    values = np.asarray(scores, dtype=np.float64)
    if values.size == 0:
        return {
            'count': 0, 'mean': None, 'std': None, 'min': None,
            'q25': None, 'median': None, 'q75': None, 'max': None,
        }
    return {
        'count': int(values.size),
        'mean': float(np.mean(values)),
        'std': float(np.std(values, ddof=0)),
        'min': float(np.min(values)),
        'q25': float(np.quantile(values, 0.25)),
        'median': float(np.median(values)),
        'q75': float(np.quantile(values, 0.75)),
        'max': float(np.max(values)),
    }


def calculate_injection_metrics(dataset, dataset_dir, segment_predictions):
    counters = {}
    cached_segment = None
    segment_data = None

    total = 0
    zero_prediction_frames = 0
    fp_counts = {1: 0, 2: 0, 3: 0}
    fp_scores = {1: [], 2: [], 3: []}
    best_ious = []
    fp_records = []

    for info in dataset.infos:
        segment = segment_name_from_info(info)
        local_idx = counters.get(segment, 0)
        counters[segment] = local_idx + 1

        if segment != cached_segment:
            with open(dataset_file(dataset_dir, segment), 'rb') as handle:
                segment_data = pkl.load(handle)
            cached_segment = segment

        frame = segment_data[local_idx]
        if str(frame['frame_id']) != str(info['frame_id']):
            raise AssertionError(
                f"Dataset frame mismatch: {frame['frame_id']} != "
                f"{info['frame_id']}"
            )
        spoof_box = frame.get('spoof_gt')
        if spoof_box is None:
            continue

        total += 1
        frame_pred = segment_predictions[segment][local_idx]
        outcome = spoof_false_positive(frame_pred, spoof_box)
        if outcome is None:
            zero_prediction_frames += 1
            continue
        best_ious.append(outcome['max_iou'])
        if outcome['is_fp']:
            fp_counts[outcome['label']] += 1
            fp_scores[outcome['label']].append(outcome['score'])
            fp_records.append({
                'segment': segment,
                'local_idx': int(local_idx),
                'frame_id': str(info['frame_id']),
                'label': outcome['label'],
                'score': outcome['score'],
                'iou': outcome['max_iou'],
                'spoof_kept_count': int(frame.get(
                    'spoof_kept_count', frame.get('n_spoof_k', 0)
                ) or 0),
            })

    asr = None if total == 0 else float(fp_counts[1] / total)
    zero_pred_rate = (
        None if total == 0 else float(zero_prediction_frames / total)
    )
    return {
        'asr': asr,
        'asr_pedestrian': None if total == 0 else float(fp_counts[2] / total),
        'asr_cyclist': None if total == 0 else float(fp_counts[3] / total),
        'n_target_frames': int(total),
        'n_vehicle_fp': int(fp_counts[1]),
        'n_pedestrian_fp': int(fp_counts[2]),
        'n_cyclist_fp': int(fp_counts[3]),
        'zero_prediction_frame_rate': zero_pred_rate,
        'fp_score_stats': score_statistics(fp_scores[1]),
        'spoof_best_iou_stats': score_statistics(best_ious),
        'fp_scores_vehicle': np.asarray(fp_scores[1], dtype=np.float32),
        'fp_scores_pedestrian': np.asarray(fp_scores[2], dtype=np.float32),
        'fp_scores_cyclist': np.asarray(fp_scores[3], dtype=np.float32),
        'spoof_best_ious': np.asarray(best_ious, dtype=np.float32),
        'fp_records': fp_records,
    }


def compute_l2_map_maph(result_dict, class_names):
    class_metrics = {}
    aps = []
    aphs = []
    aliases = {
        'VEHICLE': 'VEHICLE',
        'PEDESTRIAN': 'PEDESTRIAN',
        'CYCLIST': 'CYCLIST',
    }
    for class_name in class_names:
        canonical = aliases.get(str(class_name).upper())
        if canonical is None:
            continue
        ap_key = f'OBJECT_TYPE_TYPE_{canonical}_LEVEL_2/AP'
        aph_key = f'OBJECT_TYPE_TYPE_{canonical}_LEVEL_2/APH'
        ap = result_dict.get(ap_key)
        aph = result_dict.get(aph_key)
        class_metrics[class_name] = {
            'ap_key': ap_key,
            'aph_key': aph_key,
            'ap': None if ap is None else float(ap),
            'aph': None if aph is None else float(aph),
        }
        if ap is not None and np.isfinite(float(ap)):
            aps.append(float(ap))
        if aph is not None and np.isfinite(float(aph)):
            aphs.append(float(aph))

    expected = len(class_metrics)
    if len(aps) != expected or len(aphs) != expected:
        missing = [
            values for values in class_metrics.values()
            if values['ap'] is None or values['aph'] is None
        ]
        raise KeyError(
            'Could not calculate L2 mAP/mAPH. Missing metrics: '
            + json.dumps(missing, indent=2)
        )
    return {
        'per_class': class_metrics,
        'l2_map': float(np.mean(aps)),
        'l2_maph': float(np.mean(aphs)),
        'classes_averaged': list(class_metrics.keys()),
    }


def print_injection_summary(target_metrics):
    print('\n===== SPOOF FALSE-POSITIVE METRICS (INJECTION, CP4F) =====')
    asr = target_metrics['asr']
    print(
        f'ASR (vehicle FP rate): {asr:.6f} ({100.0 * asr:.2f}%)'
        if asr is not None else 'ASR: N/A'
    )
    print(f"Target (spoofed) frames: {target_metrics['n_target_frames']}")
    print(f"Vehicle FPs (IoU>=0.7): {target_metrics['n_vehicle_fp']}")
    print(f"Pedestrian FPs (IoU>=0.5): {target_metrics['n_pedestrian_fp']}")
    print(f"Cyclist FPs (IoU>=0.5): {target_metrics['n_cyclist_fp']}")
    print(
        'Zero-prediction frame rate: '
        f"{target_metrics['zero_prediction_frame_rate']}"
    )

    stats = target_metrics['fp_score_stats']
    print('\n===== VEHICLE FP SCORE DISTRIBUTION =====')
    print(f"N: {stats['count']}")
    for key in ('mean', 'std', 'min', 'q25', 'median', 'q75', 'max'):
        value = stats[key]
        print(f'{key}: N/A' if value is None else f'{key}: {value:.6f}')

    iou_stats = target_metrics['spoof_best_iou_stats']
    print('\n===== BEST IoU AT SPOOF LOCATION (all target frames) =====')
    print(f"N: {iou_stats['count']}")
    for key in ('mean', 'median', 'max'):
        value = iou_stats[key]
        print(f'{key}: N/A' if value is None else f'{key}: {value:.6f}')


def print_l2_summary(l2_summary):
    print('\n===== WAYMO LEVEL-2 SUMMARY (CP4F RECOMPUTED) =====')
    for class_name, values in l2_summary['per_class'].items():
        print(
            f"{class_name}: L2 AP={values['ap']:.6f} "
            f"({100.0 * values['ap']:.2f}%), "
            f"L2 APH={values['aph']:.6f} "
            f"({100.0 * values['aph']:.2f}%)"
        )
    print(
        f"L2 mAP: {l2_summary['l2_map']:.6f} "
        f"({100.0 * l2_summary['l2_map']:.2f}%)"
    )
    print(
        f"L2 mAPH: {l2_summary['l2_maph']:.6f} "
        f"({100.0 * l2_summary['l2_maph']:.2f}%)"
    )


def main():
    args = parse_args()
    logger = setup_logger('eval_cp4f_recompute')
    Path(args.pred_dir).mkdir(parents=True, exist_ok=True)
    identity = check_or_write_identity(args)
    if (
        args.resume
        and Path(args.metrics_json).is_file()
        and Path(args.summary_pkl).is_file()
    ):
        logger.info(
            'Complete metrics already exist for this verified run identity; skipping.'
        )
        return

    cfg_from_yaml_file(args.cfg_file, cfg)
    if args.data_path:
        cfg.DATA_CONFIG.DATA_PATH = args.data_path
    cfg.TAG = Path(args.cfg_file).stem
    cfg.EXP_GROUP_PATH = 'cp4f_recomputed_injection'
    class_names = list(cfg.CLASS_NAMES)
    eval_metric = cfg.MODEL.POST_PROCESSING.EVAL_METRIC

    dataset, _, _ = build_dataloader(
        dataset_cfg=cfg.DATA_CONFIG,
        class_names=cfg.CLASS_NAMES,
        batch_size=1,
        dist=False,
        workers=args.workers,
        logger=logger,
        training=False,
    )
    selected = discover_selected_segments(args.dataset, args.annos_dir)
    filter_dataset_to_selected_segments(dataset, selected)
    global_to_segment, counts, pose_map, ordered_segments = build_index_maps(
        dataset
    )
    logger.info(
        'CP4F recompute [%s]: %d frames across %d segments',
        args.label, len(dataset.infos), len(ordered_segments),
    )

    model = build_network(
        cfg.MODEL, num_class=len(cfg.CLASS_NAMES), dataset=dataset
    )
    model.load_params_from_file(args.ckpt, logger=logger, to_cpu=False)
    model.cuda().eval()

    completed = (
        validate_completed_segments(args.pred_dir, ordered_segments, counts)
        if args.resume else set()
    )
    logger.info(
        'Resume: %d complete checkpoint-specific segment files found',
        len(completed),
    )

    inference_stats = {
        'native_clean_window': 0,
        'rebuilt_corrupted_window': 0,
    }
    current_segment = None
    current_preds = None
    segment_data = None

    def flush_current():
        nonlocal current_segment, current_preds
        if current_segment is None or current_preds is None:
            return
        if len(current_preds) != counts[current_segment]:
            raise RuntimeError(
                f'Incomplete segment {current_segment}: '
                f'{len(current_preds)} != {counts[current_segment]}'
            )
        atomic_pickle_dump(
            current_preds,
            Path(args.pred_dir) / f'{current_segment}_p.pkl',
        )
        logger.info('Saved checkpoint-specific predictions: %s', current_segment)

    for global_idx in tqdm(
        range(len(dataset.infos)), desc=f'CP4F recompute [{args.label}]'
    ):
        segment, local_idx = global_to_segment[global_idx]

        if segment != current_segment:
            flush_current()
            current_segment = segment
            if segment in completed:
                current_preds = None
                segment_data = None
            else:
                with open(dataset_file(args.dataset, segment), 'rb') as handle:
                    segment_data = pkl.load(handle)
                if len(segment_data) != counts[segment]:
                    raise RuntimeError(
                        f'Dataset length mismatch for {segment}: '
                        f'{len(segment_data)} != {counts[segment]}'
                    )
                current_preds = []

        if current_preds is None:
            continue

        frame = segment_data[local_idx]
        info = dataset.infos[global_idx]
        if str(frame['frame_id']) != str(info['frame_id']):
            raise AssertionError(
                f"Generated/CP4F frame mismatch at {segment}[{local_idx}]: "
                f"{frame['frame_id']} != {info['frame_id']}"
            )

        data_dict, rebuilt = build_cp4f_item(
            dataset=dataset,
            global_idx=global_idx,
            segment=segment,
            local_idx=local_idx,
            segment_data=segment_data,
            pose_map=pose_map,
        )
        if rebuilt:
            inference_stats['rebuilt_corrupted_window'] += 1
        else:
            inference_stats['native_clean_window'] += 1

        batch = dataset.collate_batch([data_dict])
        load_data_to_gpu(batch)
        with torch.no_grad():
            pred_dicts, _ = model(batch)
        annos = dataset.generate_prediction_dicts(
            batch, pred_dicts, class_names
        )
        if len(annos) != 1:
            raise RuntimeError(f'Expected one prediction, got {len(annos)}')
        current_preds.extend(annos)

    flush_current()
    logger.info(
        'Aggregation stats for frames inferred in this invocation: %s',
        json.dumps(inference_stats, sort_keys=True),
    )
    aggregation_stats = calculate_full_aggregation_stats(
        args.dataset, ordered_segments, counts
    )
    logger.info(
        'Aggregation stats for the complete evaluation subset: %s',
        json.dumps(aggregation_stats, sort_keys=True),
    )

    segment_predictions = load_all_predictions(
        args.pred_dir, ordered_segments, counts
    )
    det_annos = assemble_det_annos(dataset, segment_predictions)

    target_metrics = calculate_injection_metrics(
        dataset, args.dataset, segment_predictions
    )
    print_injection_summary(target_metrics)

    # CVPR: Waymo metrics only where the library exists (PACE: yes; e.g. ARM Delta: no). Otherwise
    # keep the per-segment predictions + ASR and stop before summary.pkl, so a rerun resumes.
    import importlib.util as _ilu
    if os.environ.get('ATLAS_SKIP_WAYMO') == '1' or _ilu.find_spec('waymo_open_dataset') is None:
        _asr = {k: v for k, v in target_metrics.items() if not isinstance(v, np.ndarray) and k != 'fp_records'}
        atomic_json_dump({'status': 'predictions_and_asr_only', 'target_metrics': _asr},
                         str(Path(args.metrics_json).with_name('asr_only.json')))
        print('Waymo metrics unavailable: predictions + asr_only.json saved; rerun to finish the metrics')
        return
    print('\n===== FULL WAYMO EVALUATION (CP4F RECOMPUTED) =====')
    result_str, result_dict = dataset.evaluation(
        det_annos, class_names, eval_metric=eval_metric
    )
    print(result_str)
    print('\n===== WAYMO RESULT DICT =====')
    print(json.dumps(
        result_dict, indent=2, sort_keys=True, default=json_default
    ))

    l2_summary = compute_l2_map_maph(result_dict, class_names)
    print_l2_summary(l2_summary)

    output = {
        'detector': 'CP4F',
        'attack_type': 'point_injection',
        'proposal_source': 'recomputed_with_requested_checkpoint',
        'aggregation_source': 'generated_single_frame_clouds',
        'aggregation_history': 4,
        'aggregation_stats': aggregation_stats,
        'inference_stats_this_invocation': inference_stats,
        'label': args.label,
        'dataset_dir': str(Path(args.dataset).resolve()),
        'annos_dir': str(Path(args.annos_dir).resolve()),
        'cfg_file': str(Path(args.cfg_file).resolve()),
        'ckpt': str(Path(args.ckpt).resolve()),
        'run_identity': identity,
        'num_segments': len(ordered_segments),
        'num_frames': len(dataset.infos),
        'target_metrics': target_metrics,
        'waymo_metrics': result_dict,
        'l2_summary': l2_summary,
    }
    json_output = {
        key: value for key, value in output.items()
        if key != 'target_metrics'
    }
    json_output['target_metrics'] = {
        key: value for key, value in target_metrics.items()
        if key not in (
            'fp_scores_vehicle', 'fp_scores_pedestrian',
            'fp_scores_cyclist', 'spoof_best_ious', 'fp_records',
        )
    }
    atomic_json_dump(json_output, args.metrics_json)
    atomic_pickle_dump(output, args.summary_pkl)
    print(f'\nSaved metrics JSON: {args.metrics_json}')
    print(f'Saved complete summary pickle: {args.summary_pkl}')


if __name__ == '__main__':
    main()
PY

DATASET_DIR="$GENERATION_ROOT/$RUN_NAME/dataset"
ANNOS_DIR="$GENERATION_ROOT/$RUN_NAME/annos"

for base_path in "$PROJECT_ROOT" "$DATASET_DIR" "$ANNOS_DIR" "$CP_CFG"; do
    if [[ ! -e "$base_path" ]]; then
        echo "ERROR: required path does not exist: $base_path" >&2
        exit 1
    fi
done

echo "Running ${#CHECKPOINTS[@]} CP4F checkpoints sequentially on one GPU."
echo "Dataset run: $RUN_NAME"

for ENTRY in "${CHECKPOINTS[@]}"; do
    IFS='|' read -r LABEL CKPT CFG_OVERRIDE <<< "$ENTRY"
    CFG_USED="${CFG_OVERRIDE:-$CP_CFG}"

    RESULT_DIR="$GENERATION_ROOT/$RUN_NAME/evaluation/cp4f_atlas/$LABEL"
    PRED_DIR="$RESULT_DIR/predictions"
    IDENTITY_JSON="$RESULT_DIR/run_identity.json"
    METRICS_JSON="$RESULT_DIR/metrics.json"
    SUMMARY_PKL="$RESULT_DIR/summary.pkl"
    LOG_FILE="$RESULT_DIR/eval.log"

    for path in "$CFG_USED" "$CKPT"; do
        if [[ ! -e "$path" ]]; then
            echo "ERROR: required path does not exist: $path" >&2
            exit 1
        fi
    done
    if [[ "$RESUME" == "1" && -f "$SUMMARY_PKL" ]]; then
        echo "Skipping $LABEL: $SUMMARY_PKL already exists"; continue
    fi
    mkdir -p "$RESULT_DIR" "$PRED_DIR"

    if [[ "$RESUME" == "0" ]]; then
        rm -rf "$PRED_DIR"
        rm -f "$IDENTITY_JSON" "$METRICS_JSON" "$SUMMARY_PKL" "$LOG_FILE"
        mkdir -p "$PRED_DIR"
    fi

    echo "==================================================================="
    echo "CP4F recomputed injection eval"
    echo "  allocation: $SLURM_JOB_ID"
    echo "  run       : $RUN_NAME"
    echo "  label     : $LABEL"
    echo "  ckpt      : $CKPT"
    echo "  cfg       : $CFG_USED"
    echo "  output    : $RESULT_DIR"
    echo "==================================================================="

    # One srun at a time; the next checkpoint starts only after this one exits.
    srun --exclusive -N1 -n1 --gres=gpu:1 -u python "$TMP_PY" \
        --dataset "$DATASET_DIR" \
        --annos_dir "$ANNOS_DIR" \
        --cfg_file "$CFG_USED" \
        --ckpt "$CKPT" \
        --pred_dir "$PRED_DIR" \
        --identity_json "$IDENTITY_JSON" \
        --metrics_json "$METRICS_JSON" \
        --summary_pkl "$SUMMARY_PKL" \
        --label "$LABEL" \
        --data_path "$DATA_PATH" \
        --workers "$WORKERS" \
        --resume "$RESUME" \
        2>&1 | tee "$LOG_FILE"

    echo "Completed $RUN_NAME / $LABEL"
done

echo "All sequential CP4F evaluations completed."
